const fs = require('fs');
const LOG = '/agency/news-log.json';
const PENDING = '/agency/news-pending.json';
let logged = new Set();
try {
  const data = JSON.parse(fs.readFileSync(LOG, 'utf8'));
  (data.entries || []).forEach(e => { if (e.url) logged.add(e.url); });
} catch (e) {}
const items = $input.all().map(it => it.json).filter(j => j && (j.link || j.guid));
const seen = new Set();
const fresh = [];
for (const j of items) {
  const url = (j.link || j.guid || '').toString().trim();
  if (!url || logged.has(url) || seen.has(url)) continue;
  seen.add(url);
  let host = '';
  try { host = new URL(url).hostname.replace(/^www\./, ''); } catch (e) {}
  fresh.push({ title: (j.title || '').toString().trim(), link: url,
    source: (j.source || host || 'unknown'),
    snippet: (j.contentSnippet || j.content || '').toString().slice(0, 300),
    pubDate: j.isoDate || j.pubDate || '' });
}
fresh.sort((a, b) => new Date(b.pubDate || 0) - new Date(a.pubDate || 0));
const picked = fresh.slice(0, 6);
try { fs.writeFileSync(PENDING, JSON.stringify({ items: picked, ts: new Date().toISOString() })); } catch (e) {}
return picked.map(p => ({ json: p }));

let raw = '';
try { raw = $input.first().json.candidates[0].content.parts.map(p => p.text || '').join(''); } catch (e) {}
raw = raw.replace(/```json|```/g, '').trim();
const start = raw.indexOf('{'), end = raw.lastIndexOf('}');
try {
  const j = JSON.parse(raw.slice(start, end + 1));
  const posts = (j.posts || []).slice(0, 3).filter(p => p && p.post_text && p.link);
  return posts.map(p => ({ json: { title: p.title || '', post_text: p.post_text, link: p.link, source: p.source || '' } }));
} catch (e) {
  return [];
}

const fb = $input.first().json || {};
let orig = {};
try { orig = $('Parse Writer').item.json || {}; } catch (e) {}
const postId = fb.id || '';
return [{ json: { title: orig.title || '', post_text: orig.post_text || '', link: orig.link || '',
  source: orig.source || '', post_id: postId, fb_ok: !!postId,
  fb_response: postId ? '' : JSON.stringify(fb).slice(0, 300) } }];

const fs = require('fs');
const LOG = '/agency/news-log.json';
const PENDING = '/agency/news-pending.json';
let log = { entries: [] };
try { log = JSON.parse(fs.readFileSync(LOG, 'utf8')); if (!Array.isArray(log.entries)) log.entries = []; } catch (e) {}
let pending = [];
try { pending = (JSON.parse(fs.readFileSync(PENDING, 'utf8')).items || []); } catch (e) {}
const chosen = $input.all().map(it => it.json);
const chosenUrls = new Set(chosen.map(c => c.link));
const now = new Date().toISOString();
let posted = 0;
for (const p of pending) {
  const isChosen = chosenUrls.has(p.link);
  const c = chosen.find(x => x.link === p.link);
  const status = !isChosen ? 'skipped' : (c && c.fb_ok ? 'posted' : 'failed');
  if (status === 'posted') posted++;
  log.entries.push({ url: p.link, title: p.title || '', source: p.source || '',
    status, ts: now, post_id: (c && c.post_id) || '' });
}
log.entries = log.entries.slice(-1000);
try { fs.writeFileSync(LOG, JSON.stringify(log, null, 2)); } catch (e) {}
try { fs.unlinkSync(PENDING); } catch (e) {}
return [{ json: { logged: pending.length, posted, ts: now } }];
